        // forward to the next Monday. Everything derived from it (e.g. the membership
        // number's year segment) then uses the adjusted date.
        owner.setRegistrationDate(BusinessDays.toBusinessDay(owner.getRegistrationDate()));
        built.set(owner);
    }
}
